Method.Source:
    /// <summary>
    /// CehckInvoice method extension
    /// </summary>
    /// <param name = "_ledgerJournalTrans"><c>LedgerJournalTrans</c> buffer.</param>
    /// <returns>True if invoice is not found; otherwise false</returns>
    boolean checkInvoice(LedgerJournalTrans _ledgerJournalTrans)
    {
        // <GTH>
        boolean ret;
        VendTable metVendTable;
        // </GTH>

        ret = next checkInvoice(_ledgerJournalTrans);

        if (VendParameters::find().CheckInvoice == ReuseVoucher::METInvoiceValidation)
        {
            metvendTable = VendTable::findByLedgerDimension(_ledgerJournalTrans.LedgerDimension);

            ret  = metvendTable.metCheckInvoice(_ledgerJournalTrans.Invoice,
                                                _ledgerJournalTrans.DocumentDate,
                                                _ledgerJournalTrans.CurrencyCode,
                                                abs(_ledgerJournalTrans.amount()));
        }
        
        return ret;
    }

    /// <summary>
    /// Check payment status
    /// </summary>
    /// <param name = "_ledgerJournalType">LedgerJournaltype</param>
    /// <param name = "_ledgerJournalTrans"><c>ledgerJournalTrans buffer</c></param>
    /// <param name = "_ledgerPostingMessageCollection">ledgerPostingMessageCollection</param>
    /// <returns>true if status is valid, otherwise false</returns>
    public boolean checkPaymStatus(LedgerJournalType _ledgerJournalType,
                                    LedgerJournalTrans _ledgerJournalTrans,
                                    LedgerPostingMessageLog _ledgerPostingMessageCollection)
    {
        boolean metOK;

        metOk = next checkPaymStatus(_ledgerJournalType, _ledgerJournalTrans, _ledgerPostingMessageCollection);

        if (metOk
            && _ledgerJournalTrans.PaymMode == VendParameters::findByCompany(_ledgerJournalTrans.company()).METpayPaymMode)
        {
            CustVendPaymStatus metPaymStatus;
            SelectableDataArea metJournalTransCompany = _ledgerJournalTrans.company();

            if ((_ledgerJournalType == LedgerJournalType::Payment &&
                 _ledgerJournalTrans.PaymMode))
            {
                changecompany (metJournalTransCompany)
                {
                    metPaymStatus = CustVendPaymModeTable::findCommon(_ledgerJournalTrans).PaymStatus;
                }

                changecompany (metjournalTransCompany)
                {
                    metOk = CustVendPaym::metCheckPaymStatus(ModuleCustVend::Vend, _ledgerJournalTrans.PaymMode, _ledgerJournalTrans.PaymentStatus);
                }

                if (!metOk)
                {
                    if (_ledgerPostingMessageCollection)
                    {
                        _ledgerPostingMessageCollection.logCheckFailed(strFmt("@SYS66070", LedgerJournalTrans::findTmpVoucher(_ledgerJournalTrans.Voucher, tmpVoucherMap),
                            _ledgerJournalTrans.PaymentStatus,
                            metpaymStatus));
                    }
                    else
                    {
                        checkFailed(strFmt("@SYS66070", LedgerJournalTrans::findTmpVoucher(_ledgerJournalTrans.Voucher, tmpVoucherMap),
                            _ledgerJournalTrans.PaymentStatus,
                            metPaymStatus));
                    }
                }
            }
        }
        return metOk;
    }
